entries.syntax:
// The URI of the key management system, to the end of the box
aligned(8) class ISMAKMSBox extends FullBox('iKMS', 0, 0) {
 string kms_URI;
 }

// How the samples are encrypted: selectively or not, and how long their key indicators and IVs are
aligned(8) class ISMASampleFormatBox extends FullBox('iSFM', 0, 0) {
 bit(1) selective_encryption;
 bit(7) reserved;
 unsigned int(8) key_indicator_length;
 unsigned int(8) IV_length;
 }

// The salt of the key, a box and not a full box, as GPAC reads it
aligned(8) class ISMACrypSaltBox extends Box('iSLT') {
 unsigned int(64) salt;
 }
